    'prog.rule1': { ko: '1. 명령을 눌러 <b>프로그램</b>을 만들어라', en: '1. Tap commands to build a <b>program</b>', ja: '1. 命令を押して<b>プログラム</b>を作ろう', zh: '1. 点击命令，组成<b>程序</b>', hi: '1. कमांड दबाकर <b>प्रोग्राम</b> बनाओ', vi: '1. Bấm lệnh để tạo <b>chương trình</b>' },
    'prog.rule2': { ko: '2. <b>실행</b>하면 CARI가 순서대로 움직인다', en: '2. <b>Run</b> and CARI follows them in order', ja: '2. <b>実行</b>するとCARIが順番に動く', zh: '2. <b>运行</b>后 CARI 会按顺序执行', hi: '2. <b>चलाओ</b> तो CARI क्रम से चलता है', vi: '2. <b>Chạy</b> là CARI làm theo thứ tự' },
    'prog.rule3': { ko: '3. 실행은 레벨마다 <b>3번</b>뿐 — 다 쓰면 끝', en: '3. Only <b>3 runs</b> per level — use them up and it\'s over', ja: '3. 実行はレベルごとに<b>3回</b>だけ — 使い切ったら終了', zh: '3. 每关只能<b>运行 3 次</b>——用完就结束', hi: '3. हर स्तर पर सिर्फ <b>3 रन</b> — खत्म तो खेल खत्म', vi: '3. Mỗi màn chỉ <b>3 lần chạy</b> — hết là kết thúc' },
