    'reach.tut.goal1': { ko: '별에 닿아라', en: 'Reach the star', ja: '星に届け', zh: '够到星星', hi: 'तारे तक पहुँचो', vi: 'Chạm ngôi sao' },
    'reach.tut.goal2': { ko: '벽을 돌아 별로', en: 'Around the wall to the star', ja: '壁を回って星へ', zh: '绕过墙到星星', hi: 'दीवार घूमकर तारे तक', vi: 'Vòng qua tường tới sao' },
    'reach.tut.s1': { ko: '<b>아래 관절</b> 슬라이더를 밀어 보세요 — 팔 전체가 돌아요', en: 'Slide the <b>base joint</b> — the whole arm turns', ja: '<b>根元の関節</b>のスライダーを動かして — 腕全体が回ります', zh: '拖动<b>底部关节</b>滑块——整条手臂会转', hi: '<b>नीचे के जोड़</b> का स्लाइडर खिसकाओ — पूरी बांह घूमती है', vi: 'Kéo thanh <b>khớp gốc</b> — cả cánh tay xoay theo' },
    'reach.tut.s2': { ko: '<b>위 관절</b> 슬라이더는 팔꿈치만 접어요', en: 'The <b>upper joint</b> slider bends only the elbow', ja: '<b>上の関節</b>のスライダーは肘だけ曲がります', zh: '<b>上部关节</b>滑块只弯曲手肘', hi: '<b>ऊपर के जोड़</b> का स्लाइडर सिर्फ कोहनी मोड़ता है', vi: 'Thanh <b>khớp trên</b> chỉ gập khuỷu tay' },
    'reach.tut.s3': { ko: '관절 <b>동그라미를 직접 끌어도</b> 돼요', en: 'You can also <b>drag the joint circles</b> directly', ja: '関節の<b>丸を直接ドラッグ</b>してもOK', zh: '也可以<b>直接拖动关节圆点</b>', hi: 'जोड़ के <b>गोले को सीधे खींच</b> भी सकते हो', vi: 'Cũng có thể <b>kéo trực tiếp vòng tròn khớp</b>' },
    'reach.tut.s4': { ko: '이제 <b>손끝을 별에</b> 대 보세요', en: 'Now <b>touch the star</b> with the tip', ja: 'では<b>手先を星に</b>当ててみて', zh: '现在让<b>手尖碰到星星</b>', hi: 'अब <b>सिरा तारे पर</b> लगाओ', vi: 'Giờ hãy <b>chạm đầu tay vào sao</b>' },
    'reach.tut.s5': { ko: '팔이 <b>붉으면 벽에 닿은</b> 거예요 — 이 상태로는 인정이 안 돼요. 관절을 돌려 벽에서 떼요', en: 'A <b>red arm is touching a wall</b> — it won\'t count like this. Turn the joints away from the wall', ja: '腕が<b>赤いのは壁に当たっている</b>印 — このままでは無効です。関節を回して壁から離して', zh: '手臂<b>变红表示碰到墙</b>——这样不算数。转动关节离开墙壁', hi: 'बांह <b>लाल है तो दीवार से लगी है</b> — ऐसे नहीं गिना जाएगा। जोड़ घुमाकर दीवार से हटाओ', vi: 'Tay <b>đỏ là đang chạm tường</b> — không được tính. Xoay khớp rời khỏi tường' },
    'reach.tut.s6': { ko: '벽을 <b>돌아서</b> 별에 닿아요', en: 'Go <b>around</b> the wall to the star', ja: '壁を<b>回って</b>星に届け', zh: '<b>绕过</b>墙壁够到星星', hi: 'दीवार <b>घूमकर</b> तारे तक पहुँचो', vi: '<b>Vòng qua</b> tường để chạm sao' },
    'reach.tut.good_next': { ko: '좋아요! 다음 — <b>{title}</b>', en: 'Nice! Next — <b>{title}</b>', ja: 'いいね！次は — <b>{title}</b>', zh: '不错！下一步——<b>{title}</b>', hi: 'बढ़िया! अगला — <b>{title}</b>', vi: 'Tốt! Tiếp theo — <b>{title}</b>' },
    'reach.tut.good': { ko: '좋아요!', en: 'Nice!', ja: 'いいね！', zh: '不错！', hi: 'बढ़िया!', vi: 'Tốt!' },
    'reach.tut.done': { ko: '튜토리얼 끝!', en: 'Tutorial done!', ja: 'チュートリアル終了！', zh: '教程结束！', hi: 'ट्यूटोरियल पूरा!', vi: 'Xong hướng dẫn!' },
